mapper.select:
WITH observed AS ( INSERT INTO public.ban_submission_target AS state ( app_id, target, peer_network, peer_port, module_name, rule_name, first_seen, last_seen, window_seen, window_ban_at, latest_ban_at, windows, peak_windows, replays ) SELECT #{appId}, incoming.target, network(set_masklen(incoming.ip, CASE family(incoming.ip) WHEN 4 THEN 24 ELSE 64 END))::text, incoming.port, incoming.module, incoming.rule, #{now}, #{now}, CASE WHEN incoming.latest > #{quietCutoff} THEN #{now} END, CASE WHEN incoming.latest > #{quietCutoff} THEN incoming.latest END, incoming.latest, CASE WHEN incoming.latest > #{quietCutoff} THEN 1 ELSE 0 END, CASE WHEN incoming.latest > #{quietCutoff} THEN 1 ELSE 0 END, incoming.replays FROM (VALUES
(CAST(#{row.hash} AS uuid), CAST(#{row.ip} AS inet), #{row.port}, #{row.module}, CAST(#{row.rule,jdbcType=VARCHAR} AS text), CAST(#{row.latest,jdbcType=TIMESTAMP_WITH_TIMEZONE} AS timestamptz), #{row.replays})
) AS incoming(target, ip, port, module, rule, latest, replays) ORDER BY incoming.target ON CONFLICT (app_id, target) DO UPDATE SET last_seen = GREATEST(state.last_seen, EXCLUDED.last_seen), latest_ban_at = GREATEST(state.latest_ban_at, EXCLUDED.latest_ban_at), window_seen = CASE WHEN THEN EXCLUDED.window_seen ELSE state.window_seen END, window_ban_at = CASE WHEN THEN EXCLUDED.window_ban_at ELSE state.window_ban_at END, windows = CASE WHEN THEN ELSE state.windows END, peak_windows = CASE WHEN THEN GREATEST(state.peak_windows, ) ELSE state.peak_windows END, detected = state.detected OR (), detection_hits = CASE WHEN THEN GREATEST(state.detection_hits, CASE WHEN state.detected THEN 1 ELSE 0 END) + 1 ELSE state.detection_hits END, replays = state.replays + EXCLUDED.replays RETURNING target, windows, window_seen ) SELECT target::text FROM observed WHERE #{suppression} AND windows >= #{threshold} AND window_seen > #{quietCutoff}

mapper.update:
UPDATE public.ban_submission_target AS state SET suppressed = state.suppressed + incoming.total FROM (VALUES
(CAST(#{row.hash} AS uuid), #{row.count})
) AS incoming(target, total) WHERE state.app_id = #{appId} AND state.target = incoming.target

