WHERE (detected OR replays > 0)
AND app_id = #{query.appId}
AND last_seen >= #{query.since}
AND last_seen <= #{query.until}
AND replays > 0
AND detected
AND () = #{query.status}

mapper.delete:
WITH expired_state AS (
    SELECT app_id, target FROM public.ban_submission_target
    WHERE NOT detected AND replays = 0 AND last_seen < #{stateCutoff}
    ORDER BY last_seen
    LIMIT #{limit}
    FOR UPDATE SKIP LOCKED
), expired_events AS (
    SELECT app_id, target FROM public.ban_submission_target
    WHERE (detected OR replays > 0) AND last_seen < #{eventCutoff}
    ORDER BY last_seen
    LIMIT #{limit}
    FOR UPDATE SKIP LOCKED
)
DELETE FROM public.ban_submission_target
WHERE (app_id, target) IN (
    SELECT app_id, target FROM expired_state
    UNION ALL
    SELECT app_id, target FROM expired_events
)
